import{_ as t,o as a,c as o,ae as i}from"./chunks/framework.Dh1jimFm.js";const u=JSON.parse('{"title":"Find & Replace","description":"","frontmatter":{},"headers":[],"relativePath":"editor/find-replace.md","filePath":"editor/find-replace.md"}'),r={name:"editor/find-replace.md"};function n(l,e,s,d,c,h){return a(),o("div",null,e[0]||(e[0]=[i('<h1 id="find-replace" tabindex="-1">Find &amp; Replace <a class="header-anchor" href="#find-replace" aria-label="Permalink to &quot;Find &amp; Replace&quot;">​</a></h1><p>Supervertaler&#39;s Find &amp; Replace feature helps you quickly find text and make consistent changes across your translation.</p><h2 id="opening-find-replace" tabindex="-1">Opening Find &amp; Replace <a class="header-anchor" href="#opening-find-replace" aria-label="Permalink to &quot;Opening Find &amp; Replace&quot;">​</a></h2><ul><li>Press <code>Ctrl+F</code> or <code>Ctrl+H</code></li><li>Or go to <strong>Edit → Find &amp; Replace</strong></li></ul><h2 id="basic-usage" tabindex="-1">Basic Usage <a class="header-anchor" href="#basic-usage" aria-label="Permalink to &quot;Basic Usage&quot;">​</a></h2><h3 id="finding-text" tabindex="-1">Finding Text <a class="header-anchor" href="#finding-text" aria-label="Permalink to &quot;Finding Text&quot;">​</a></h3><ol><li>Type your search term in the <strong>Find</strong> field</li><li>Click <strong>Find All</strong> to see all matches</li><li>Matches are highlighted in yellow in the grid</li><li>The results counter shows how many matches were found</li></ol><h3 id="replacing-text" tabindex="-1">Replacing Text <a class="header-anchor" href="#replacing-text" aria-label="Permalink to &quot;Replacing Text&quot;">​</a></h3><ol><li>Type your search term in the <strong>Find</strong> field</li><li>Type your replacement in the <strong>Replace</strong> field</li><li>Click <strong>Replace All</strong> to replace all occurrences</li><li>A confirmation shows how many replacements were made</li></ol><h2 id="search-options" tabindex="-1">Search Options <a class="header-anchor" href="#search-options" aria-label="Permalink to &quot;Search Options&quot;">​</a></h2><h3 id="match-mode" tabindex="-1">Match Mode <a class="header-anchor" href="#match-mode" aria-label="Permalink to &quot;Match Mode&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Mode</th><th>Description</th></tr></thead><tbody><tr><td><strong>Contains</strong></td><td>Matches anywhere in the text</td></tr><tr><td><strong>Whole Word</strong></td><td>Only matches complete words</td></tr><tr><td><strong>Starts With</strong></td><td>Matches at the beginning of text</td></tr><tr><td><strong>Ends With</strong></td><td>Matches at the end of text</td></tr><tr><td><strong>Regex</strong></td><td>Use regular expressions</td></tr></tbody></table><h3 id="case-sensitivity" tabindex="-1">Case Sensitivity <a class="header-anchor" href="#case-sensitivity" aria-label="Permalink to &quot;Case Sensitivity&quot;">​</a></h3><p>Toggle <strong>Case Sensitive</strong> to:</p><ul><li>✅ <strong>On</strong>: &quot;Hello&quot; won&#39;t match &quot;hello&quot;</li><li>❌ <strong>Off</strong>: &quot;Hello&quot; matches &quot;hello&quot;, &quot;HELLO&quot;, etc.</li></ul><h3 id="search-scope" tabindex="-1">Search Scope <a class="header-anchor" href="#search-scope" aria-label="Permalink to &quot;Search Scope&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Scope</th><th>Description</th></tr></thead><tbody><tr><td><strong>Source + Target</strong></td><td>Search in both columns</td></tr><tr><td><strong>Source Only</strong></td><td>Search only in source text</td></tr><tr><td><strong>Target Only</strong></td><td>Search only in translations</td></tr></tbody></table><h2 id="history-dropdowns" tabindex="-1">History Dropdowns <a class="header-anchor" href="#history-dropdowns" aria-label="Permalink to &quot;History Dropdowns&quot;">​</a></h2><p>Both the Find and Replace fields remember your recent searches:</p><ul><li>Click the dropdown arrow to see your last 20 entries</li><li>Start typing to filter the history</li><li>History persists between sessions</li></ul><h2 id="f-r-sets-batch-operations" tabindex="-1">F&amp;R Sets (Batch Operations) <a class="header-anchor" href="#f-r-sets-batch-operations" aria-label="Permalink to &quot;F&amp;R Sets (Batch Operations)&quot;">​</a></h2><p>Save and reuse multiple find/replace operations as a set.</p><h3 id="creating-a-set" tabindex="-1">Creating a Set <a class="header-anchor" href="#creating-a-set" aria-label="Permalink to &quot;Creating a Set&quot;">​</a></h3><ol><li>Expand the <strong>📁 F&amp;R Sets</strong> panel</li><li>Click <strong>➕ New Set</strong></li><li>Give your set a name (e.g., &quot;Client Style Guide&quot;)</li><li>The set appears in the dropdown</li></ol><h3 id="adding-operations-to-a-set" tabindex="-1">Adding Operations to a Set <a class="header-anchor" href="#adding-operations-to-a-set" aria-label="Permalink to &quot;Adding Operations to a Set&quot;">​</a></h3><ol><li>Enter your Find and Replace terms</li><li>Set your options (case, scope, mode)</li><li>Click <strong>➕ Add Current to Set</strong></li><li>The operation is saved to the active set</li></ol><h3 id="managing-operations" tabindex="-1">Managing Operations <a class="header-anchor" href="#managing-operations" aria-label="Permalink to &quot;Managing Operations&quot;">​</a></h3><p>In the F&amp;R Sets panel:</p><ul><li>✅ Enable/disable individual operations</li><li>📝 Edit operations (double-click)</li><li>⬆️⬇️ Reorder operations</li><li>🗑️ Delete operations</li></ul><h3 id="running-a-batch" tabindex="-1">Running a Batch <a class="header-anchor" href="#running-a-batch" aria-label="Permalink to &quot;Running a Batch&quot;">​</a></h3><ol><li>Select your set from the dropdown</li><li>Click <strong>▶️ Run All</strong></li><li>A progress dialog shows each operation</li><li>See how many replacements were made</li></ol><h3 id="importing-exporting-sets" tabindex="-1">Importing &amp; Exporting Sets <a class="header-anchor" href="#importing-exporting-sets" aria-label="Permalink to &quot;Importing &amp; Exporting Sets&quot;">​</a></h3><p>Share sets with colleagues:</p><ul><li><strong>Export</strong>: Click <strong>📤 Export Set</strong> to save as <code>.svfr</code> file</li><li><strong>Import</strong>: Click <strong>📥 Import Set</strong> to load a shared file</li></ul><h2 id="use-cases" tabindex="-1">Use Cases <a class="header-anchor" href="#use-cases" aria-label="Permalink to &quot;Use Cases&quot;">​</a></h2><h3 id="terminology-consistency" tabindex="-1">Terminology Consistency <a class="header-anchor" href="#terminology-consistency" aria-label="Permalink to &quot;Terminology Consistency&quot;">​</a></h3><p>Create a set for client-specific terms:</p><ul><li>&quot;colour&quot; → &quot;color&quot; (US spelling)</li><li>&quot;organisation&quot; → &quot;organization&quot;</li><li>&quot;programme&quot; → &quot;program&quot;</li></ul><h3 id="style-guide-rules" tabindex="-1">Style Guide Rules <a class="header-anchor" href="#style-guide-rules" aria-label="Permalink to &quot;Style Guide Rules&quot;">​</a></h3><p>Enforce style guidelines:</p><ul><li>Double spaces → Single space</li><li>&quot;e.g.&quot; → &quot;for example&quot;</li><li>Straight quotes → Curly quotes</li></ul><h3 id="post-translation-cleanup" tabindex="-1">Post-Translation Cleanup <a class="header-anchor" href="#post-translation-cleanup" aria-label="Permalink to &quot;Post-Translation Cleanup&quot;">​</a></h3><p>Clean up common MT artifacts:</p><ul><li>Remove unwanted spaces before punctuation</li><li>Fix capitalization issues</li><li>Normalize formatting</li></ul><h2 id="tips" tabindex="-1">Tips <a class="header-anchor" href="#tips" aria-label="Permalink to &quot;Tips&quot;">​</a></h2><div class="tip custom-block"><p class="custom-block-title">TIP</p><p><strong>Pro Tip:</strong> Use regex mode for complex patterns. For example, <code>\\s+</code> matches any whitespace to clean up extra spaces.</p></div><div class="info custom-block"><p class="custom-block-title">INFO</p><p><strong>Undo Support:</strong> All replacements can be undone with <code>Ctrl+Z</code> (within the same session).</p></div>',47)]))}const g=t(r,[["render",n]]);export{u as __pageData,g as default};
